// The public errors of the family: what a handler returns, as the Code of a *runtime.PublicError, and a caller tells apart with IsError.
const (
	// ErrorDenied: The caller is denied
	ErrorDenied = "denied"
)

// Errors is every public error code the family declares.
var Errors = []string{ErrorDenied}

// IsError reports whether an error is, or wraps, the family's public error of the code.
func IsError(err error, code string) bool {
	var public *runtime.PublicError
	return errors.As(err, &public) && public.Code == code
}
